"""Single-use offline consultation; no provider processes or recovery paths."""
from dataclasses import asdict, dataclass
from enum import StrEnum
from functools import wraps
from threading import RLock
from hashlib import sha256
import json
import math
import os
from pathlib import Path
from typing import Callable


class ContractError(ValueError):
    pass


class State(StrEnum):
    WORKING = "WORKING"
    CONSULT_REQUESTED = "CONSULT_REQUESTED"
    RESERVED = "RESERVED"
    ADVICE_RECEIVED = "ADVICE_RECEIVED"
    CONTINUING = "CONTINUING"
    TASK_ACCEPTED = "TASK_ACCEPTED"
    TASK_REJECTED = "TASK_REJECTED"
    STOPPED = "STOPPED"


def digest(value: object) -> str:
    return sha256(json.dumps(value, sort_keys=True, ensure_ascii=False,
                             separators=(",", ":")).encode()).hexdigest()


@dataclass(frozen=True)
class Profile:
    provider: str
    model: str
    effort: str
    tools: tuple[str, ...] = ()
    permissions: tuple[str, ...] = ()
    context_policy: str = "bounded"
    capabilities: tuple[str, ...] = ("offline", "identity", "same_session")


@dataclass(frozen=True)
class Input:
    path: str
    status: str  # tracked, dirty, untracked; content is scoped synthetic evidence
    content: str


@dataclass(frozen=True)
class Task:
    outcome: str
    criteria: tuple[str, ...]
    invariants: tuple[str, ...]
    authority: tuple[str, ...]
    stop_conditions: tuple[str, ...]

    @property
    def fingerprint(self) -> str:
        return digest(asdict(self))


@dataclass(frozen=True)
class Boundary:
    native_session: str
    runtime: str
    user_turn: str
    worker: Profile
    task_hash: str
    inputs: tuple[Input, ...]
    quiescent: bool = True

    @property
    def snapshot(self) -> str:
        return digest([asdict(item) for item in self.inputs])


@dataclass(frozen=True)
class Request:
    request_id: str
    run: str
    milestone: str
    task: Task
    boundary: Boundary
    advisor: Profile
    kind: str
    question: str
    evidence: tuple[str, ...]
    assumptions: tuple[str, ...]
    created_at: float
    expires_at: float

    @property
    def binding(self) -> str:
        return digest(asdict(self))

    def validate(self, now: float) -> None:
        if not all((self.request_id, self.run, self.milestone, self.question.strip(),
                    self.task.outcome.strip(), self.task.criteria,
                    self.task.stop_conditions, self.boundary.native_session,
                    self.boundary.runtime, self.boundary.user_turn)):
            raise ContractError("MISSING_CONTRACT")
        if self.kind not in {"stronger_reasoning", "domain_expertise", "independent_peer"}:
            raise ContractError("INVALID_KIND")
        if (not all(math.isfinite(t) for t in (self.created_at, now, self.expires_at))
                or not self.created_at <= now < self.expires_at):
            raise ContractError("STALE_REQUEST")
        if self.boundary.task_hash != self.task.fingerprint or not self.boundary.quiescent:
            raise ContractError("INVALID_BOUNDARY")
        if (len(set(self.task.criteria)) != len(self.task.criteria)
                or any(not criterion.strip() for criterion in self.task.criteria)):
            raise ContractError("INVALID_CRITERIA")
        paths = [item.path for item in self.boundary.inputs]
        if len(paths) != len(set(paths)) or any(
            item.status not in {"tracked", "dirty", "untracked"}
            for item in self.boundary.inputs
        ):
            raise ContractError("INVALID_MANIFEST")
        for profile in (self.boundary.worker, self.advisor):
            if (profile.provider not in {"codex", "claude"} or not profile.model
                    or not {"offline", "identity", "same_session"} <= set(profile.capabilities)
                    or not set(profile.permissions) <= set(self.task.authority)
                    or not set(profile.tools) <= set(self.task.authority)):
                raise ContractError("INELIGIBLE_PROFILE")
        if len(json.dumps(asdict(self), ensure_ascii=False).encode("utf-8")) > 12_000:
            raise ContractError("PACKET_TOO_LARGE")


@dataclass(frozen=True)
class Answer:
    binding: str
    observed_advisor: Profile
    kind: str
    recommendation: str
    missing_evidence: tuple[str, ...]
    experiment: str
    disproof: str
    transport_complete: bool = True


@dataclass(frozen=True)
class Acceptance:
    task_hash: str
    criteria: tuple[tuple[str, bool | None], ...]
    evidence: tuple[str, ...]
    grader: str
    rubric: str
    independent: bool
    critical_violations: tuple[str, ...] = ()
    independence_limits: str = "synthetic deterministic oracle only"

    def accepted(self, task: Task) -> bool:
        return (self.task_hash == task.fingerprint and self.independent
                and bool(self.grader and self.rubric and self.evidence)
                and not self.critical_violations
                and len(self.criteria) == len(task.criteria)
                and dict(self.criteria).keys() == set(task.criteria)
                and all(value is True for _, value in self.criteria))


class ReservationStore:
    """Private local directory, one process-independent writer per native session.

    Attempt markers are permanent. A crash leaves consumed/locked evidence;
    there is deliberately no recovery or stale-lock removal API.
    """

    def __init__(self, root: Path):
        self.root = root
        root.mkdir(parents=True, exist_ok=True)

    def _create(self, name: str, payload: dict) -> Path:
        path = self.root / name
        try:
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError as exc:
            raise ContractError("ALREADY_RESERVED") from exc
        with os.fdopen(fd, "w") as stream:
            json.dump(payload, stream, sort_keys=True)
            stream.flush()
            os.fsync(stream.fileno())
        directory = os.open(self.root, os.O_RDONLY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
        return path

    def reserve(self, run: str, task_hash: str, milestone: str,
                boundary: Boundary, binding: str) -> Path:
        # Session aliases never participate in this physical identity key.
        lock = self._create("writer-" + digest((boundary.worker.provider,
                                                boundary.native_session)),
                            {"binding": binding})
        try:
            self._create("attempt-" + digest((run, task_hash, milestone)),
                         {"binding": binding, "status": "consumed_before_effect"})
        except ContractError:
            lock.unlink()  # Only our newly acquired lock, never another owner's.
            raise
        return lock


def serialized(method):
    """Serialize state transitions, including consumption before callback effects."""
    @wraps(method)
    def wrapped(self, *args, **kwargs):
        with self._mutex:
            return method(self, *args, **kwargs)
    return wrapped


class Consultation:
    """Controller-owned allowance: request IDs cannot reset the bound milestone."""

    def __init__(self, store: ReservationStore, run: str, milestone: str,
                 task: Task, boundary: Boundary):
        self._mutex = RLock()
        self.store, self.run, self.milestone = store, run, milestone
        self.task, self.boundary = task, boundary
        self.state = State.WORKING
        self.request: Request | None = None
        self.answer: Answer | None = None
        self.accepted_advisor: Profile | None = None
        self.events: list[dict] = []
        self._lock: Path | None = None

    def _event(self, kind: str, **data: object) -> None:
        self.events.append({"sequence": len(self.events), "kind": kind,
                            "state": self.state.value, **data})

    @serialized
    def reserve(self, request: Request, now: float) -> None:
        if self.state != State.WORKING:
            raise ContractError("ATTEMPT_CONSUMED")
        request.validate(now)
        if (request.run, request.milestone, request.task, request.boundary) != (
                self.run, self.milestone, self.task, self.boundary):
            raise ContractError("CONTROLLER_BINDING_MISMATCH")
        self.state = State.CONSULT_REQUESTED
        self.request = request
        try:
            self._lock = self.store.reserve(self.run, self.task.fingerprint,
                                           self.milestone, self.boundary, request.binding)
        except Exception:
            self.state = State.STOPPED
            raise
        self.state = State.RESERVED
        self._event("attempt_reserved", binding=request.binding)

    @serialized
    def receive(self, answer: Answer, now: float) -> bool:
        if self.state != State.RESERVED or self.request is None:
            raise ContractError("NOT_RESERVED")
        reason = None
        if not math.isfinite(now) or not self.request.created_at <= now < self.request.expires_at:
            reason = "TIMED_OUT"
        elif not isinstance(answer, Answer):
            reason = "MALFORMED_ANSWER"
        elif answer.binding != self.request.binding:
            reason = "ANSWER_BINDING_MISMATCH"
        elif answer.observed_advisor != self.request.advisor:
            reason = "MODEL_MISMATCH"
        elif not answer.transport_complete:
            reason = "TRANSPORT_INCOMPLETE"
        elif answer.kind not in {"ADVICE", "NEEDS_EVIDENCE"}:
            reason = "MALFORMED_ANSWER"
        elif answer.kind == "NEEDS_EVIDENCE" or answer.missing_evidence:
            reason = "NEEDS_EVIDENCE"
        elif not all(isinstance(v, str) and v.strip() for v in (
                answer.recommendation, answer.experiment, answer.disproof)):
            reason = "EMPTY_ANSWER"
        if reason:
            self._event("answer_rejected", reason=reason)
            # Invalid observations never establish a trusted identity baseline.
            return False
        self.answer = answer
        self.accepted_advisor = answer.observed_advisor
        self.state = State.ADVICE_RECEIVED
        self._event("advisory_receipt", transport_complete=True)
        return True

    @serialized
    def deliver(self, current: Boundary, now: float,
                sink: Callable[[str, Answer], None]) -> None:
        if self.state != State.ADVICE_RECEIVED or self.request is None:
            raise ContractError("NOT_DELIVERABLE")
        if (current != self.boundary or not math.isfinite(now)
                or not self.request.created_at <= now < self.request.expires_at):
            self.stop("STALE_WORKER_BOUNDARY")
            raise ContractError("STALE_WORKER_BOUNDARY")
        self.state = State.CONTINUING  # Consume delivery before effects.
        self._event("delivery_reserved")
        try:
            sink(current.native_session, self.answer)
        except Exception:
            self.stop("UNKNOWN_DELIVERY")
            raise
        self._event("advice_delivered", session=current.native_session)

    @serialized
    def finish(self, receipt: Acceptance) -> None:
        if self.state != State.CONTINUING:
            raise ContractError("WORKER_NOT_CONTINUING")
        self.state = State.TASK_ACCEPTED if receipt.accepted(self.task) else State.TASK_REJECTED
        self._event("acceptance", receipt=asdict(receipt))
        self._release()

    @serialized
    def stop(self, reason: str) -> None:
        if self.state in {State.TASK_ACCEPTED, State.TASK_REJECTED, State.STOPPED}:
            raise ContractError("ALREADY_TERMINAL")
        self.state = State.STOPPED
        self._event("stopped", reason=reason)
        # An ambiguous effect retains its physical lock; no blind resume.
        if reason not in {"UNKNOWN_DELIVERY", "UNKNOWN_SUBMISSION", "CRASH"}:
            self._release()

    def _release(self) -> None:
        if self._lock is not None:
            self._lock.unlink()
            self._lock = None
